import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"AI 體驗流程 × 可手動畫面 — 規劃 SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"product/ai-experience-plan.md","filePath":"product/ai-experience-plan.md"}'),r={name:"product/ai-experience-plan.md"};function c(n,t,l,s,i,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ai-體驗流程-×-可手動畫面-—-規劃-ssot" tabindex="-1">AI 體驗流程 × 可手動畫面 — 規劃 SSOT <a class="header-anchor" href="#ai-體驗流程-×-可手動畫面-—-規劃-ssot" aria-label="Permalink to &quot;AI 體驗流程 × 可手動畫面 — 規劃 SSOT&quot;">​</a></h1><blockquote><p>決策日：2026-07-08 · 對齊：T-2026-020（Defensive GenUI + dual-path）、<a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>、<a href="https://github.com/tessOu56/explore-design-sdk" target="_blank" rel="noreferrer">explore-design-sdk PROJECT-PLAN Phase 1</a> 原則：<strong>每一條 AI 流程都有對應的手動操作路徑</strong>。AI 是加速器，不是唯一入口；AI 失敗、降級或使用者不信任時，同一任務可純手動完成。 上層定位與 agentic 分階段路線圖見 <a href="./agentic-integration-review.html">agentic-integration-review.md</a>（2026-07-09）。</p></blockquote><h2 id="_1-雙路徑-dual-path-原則" tabindex="-1">1. 雙路徑（dual-path）原則 <a class="header-anchor" href="#_1-雙路徑-dual-path-原則" aria-label="Permalink to &quot;1. 雙路徑（dual-path）原則&quot;">​</a></h2><table tabindex="0"><thead><tr><th>規則</th><th>說明</th></tr></thead><tbody><tr><td>任務完備</td><td>每個使用者任務（搜尋、篩選、申請、建立、追蹤）都有手動 UI 可獨立完成，不依賴 LLM</td></tr><tr><td>AI 可降級</td><td>agent 逾時/guardrail 攔截/信心不足 → 自動退到手動畫面並保留使用者輸入（預填篩選、表單）</td></tr><tr><td>狀態同步</td><td>AI 路徑產生的中間狀態（篩選條件、表單草稿）寫入 URL/store，手動畫面可接手續作</td></tr><tr><td>可稽核</td><td>AI 代填/代選的欄位有視覺標記，使用者可逐項確認或改寫</td></tr><tr><td>E2E 雙軌</td><td>每條流程的 E2E 同時驗 AI 路徑與手動路徑（T-2026-020 既有方向，擴為全站規範）</td></tr></tbody></table><h2 id="_2-流程-×-畫面對照表" tabindex="-1">2. 流程 × 畫面對照表 <a class="header-anchor" href="#_2-流程-×-畫面對照表" aria-label="Permalink to &quot;2. 流程 × 畫面對照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任務</th><th>AI 路徑</th><th>手動路徑</th><th>狀態</th></tr></thead><tbody><tr><td>目錄搜尋</td><td>LUI 對話（<code>api.chat</code> + agent-core SSE）→ 生成篩選條件 → 導向結果</td><td><code>/catalog-search</code> 篩選（<code>?type=</code> + 分頁）</td><td>手動 ✅ / AI→手動預填 ✅（2026-07-09：<code>AiFallbackPanel</code> 於 chat 失敗時帶 <code>?q=</code>+<code>?type=</code> 預填接手；URL 契約收斂於 <code>catalog-search-url.ts</code>）</td></tr><tr><td>項目瀏覽</td><td>LUI 引導到唯讀 items 列表</td><td><code>/items</code> 列表</td><td>手動 ✅ / AI 代填標記 ⬜</td></tr><tr><td>Metadata 存取申請</td><td><code>access-requests.evaluate</code> AI 預審 + 建議</td><td>申請表單 + 人工送出（G1 flow）</td><td>AI 評估 ✅ / 申請畫面 ⬜（T-2026-023）</td></tr><tr><td>資產/血緣檢視</td><td>LUI 問答（「這個資產上游是誰」）</td><td><code>/metadata/$assetId</code> + Lineage DAG（T-2026-016）</td><td>手動 🔄</td></tr><tr><td>Insights</td><td>AI 摘要（依目前資訊 + 下一步）</td><td>圖表 + 手動 metric 選擇（<code>api.context.metrics</code>）</td><td>手動 🔄</td></tr><tr><td>Context pack 切換</td><td>agent 依對話自動選 pack</td><td><code>pack-select</code> 手動指定</td><td>兩者 ✅，缺 UI 標示 ⬜</td></tr></tbody></table><p>缺口優先序：① AI→手動預填（搜尋）✅（2026-07-09）② AI 代填視覺標記（items/申請）③ 降級 fallback 統一元件（<code>AiFallbackPanel</code>）✅ 首發（2026-07-09，chat 錯誤/斷線觸發；逾時與信心不足觸發待 T-2026-020）。</p><h2 id="_3-外接元件系統-explore-design-sdk-接入" tabindex="-1">3. 外接元件系統（explore-design-sdk）接入 <a class="header-anchor" href="#_3-外接元件系統-explore-design-sdk-接入" aria-label="Permalink to &quot;3. 外接元件系統（explore-design-sdk）接入&quot;">​</a></h2><p><strong>決策（2026-07-08）</strong>：portal 視覺層全面改用 explore-design-sdk，portal 不再自持 design tokens 與基礎元件。</p><table tabindex="0"><thead><tr><th>階段</th><th>內容</th><th>出口條件</th></tr></thead><tbody><tr><td><strong>S1 tokens</strong> ✅</td><td>2026-07-08 完成：SDK <code>portal</code> map 對齊 portal 亮色主題 → <code>tokens.portal.css</code>（vendored generated）→ <code>app/tailwind.css</code> 只留 shadcn 橋接；<code>tailwind.config</code> 改 <code>var(--x)</code> 全值；<code>data-app=&quot;portal&quot;</code> 掛 <code>&lt;html&gt;</code>；dark theme 暫留 portal（S2 移 SDK）</td><td>視覺 diff 為零（值逐項對齊）、SDK CI <code>tokens:validate</code> 綠；<strong>待本機 <code>pnpm dev</code> 目視確認</strong></td></tr><tr><td><strong>S2 components</strong> 🔄</td><td>2026-07-08：<code>@is_tess/components</code> 已建（9 元件上移為 canonical，portal 端暫為 vendored 副本）；<strong>和色色盤</strong>換裝（生成り紙底 + 藍主色 + 紙紋理，見 DESIGN_SYSTEM.md 色盤段）。待 npm 發布後 portal 改 import、清空 <code>app/components/ui</code></td><td>portal <code>app/components/ui</code> 清空、typecheck/E2E 綠</td></tr><tr><td><strong>S3 LUI 語義層</strong></td><td>評估 <code>shared/lui/*</code>（ChatBubble 等）：通用者入 SDK，產品專屬留 portal</td><td>邊界文件化於 DESIGN_SYSTEM.md</td></tr></tbody></table><p>限制：<code>components/shared/chat</code>、<code>components/app</code> 為產品組合層，<strong>不外移</strong>。Token canonical 從 portal repo 移轉為 SDK repo（DESIGN_SYSTEM.md「Token Source of Truth」段落隨 S1 改寫）。</p><h2 id="_4-與生態的邊界" tabindex="-1">4. 與生態的邊界 <a class="header-anchor" href="#_4-與生態的邊界" aria-label="Permalink to &quot;4. 與生態的邊界&quot;">​</a></h2><ul><li>本文件不含任何公司鏡像業務內容與術語；展示一律用 food/recipe mock domain。</li><li>練習 repo（nx-playground、polyglot-labs 等）作為情境靈感來源，成熟能力經 SDK 或 contracts 引入，不直接複製碼。</li><li>進度回報：platform-command <code>planning/projects/ai-search-portal.md</code>。</li></ul>',13)])])}const m=e(r,[["render",c]]);export{g as __pageData,m as default};
